export const HIRAKUD_DATA={id:"hirakud-reservoir-wetland-explorer",name:"Hirakud Reservoir Wetland Explorer",subtitle:"The Reservoir Behind the World's Longest Earthen Dam",location:"Sambalpur, Bargarh, Bolangir & Subarnapur Districts, Odisha",ramsarSiteNo:2494,ramsarDeclared:2021,area:"743 km² (Full Reservoir Level)",damLength:"25.8 km (including dykes)",type:"Man-made Reservoir on the Mahanadi River",coordinates:{lat:21.57,lng:83.87},stats:[{label:"Reservoir Area",value:"743 km²",icon:"🌊"},{label:"Shoreline Length",value:"639 km",icon:"🏞️"},{label:"Bird Species Recorded",value:"130+",icon:"🦆"},{label:"Installed Hydropower",value:"347.5 MW",icon:"⚡"}],reservoirHistory:{title:"India's First Post-Independence River Valley Project",content:'Before the dam, the Mahanadi River was known across Odisha as the "Sorrow of Odisha" for the floods it regularly sent through the delta. Governor Hawthorne Lewis laid the foundation stone in March 1946, and Jawaharlal Nehru poured the first batch of concrete two years later. Construction stretched through the early 1950s, and Nehru formally inaugurated the completed dam on 13 January 1957 — one of the first major multipurpose river valley projects taken up after independence. Filling the reservoir meant submerging the Padampur valley, along with more than 200 villages and a number of centuries-old temples. In the dry summer months of May and June, falling water levels still expose the spires of some of those temples, a reminder of what the valley looked like before the dam.'},ramsarSite:{title:"A Working Reservoir Recognised as a Wetland of International Importance",content:"Hirakud Reservoir was designated a Ramsar Site on 12 October 2021, part of a larger batch of Indian wetlands announced through 2021 and 2022. It is an unusual entry on the Ramsar list: unlike most designated wetlands, Hirakud is an actively engineered reservoir that still does the everyday work of flood control, irrigation, and power generation for a large part of western and coastal Odisha. Its listing recognises that decades of human engineering can still produce a wetland with real ecological value, supporting fish, birds, and other wildlife alongside its industrial role."},waterManagement:{title:"Flood Control, Irrigation & Power in One System",content:"The Hirakud project regulates roughly 83,400 km² of the Mahanadi's catchment, holding back monsoon flows that once devastated the delta around Cuttack and Puri and releasing them in a controlled way through the Bargarh Main Canal, Sason Canal, and Sambalpur Canal. The reservoir irrigates well over 235,000 hectares of farmland across the Sambalpur, Bargarh, Bolangir, and Subarnapur districts, turning the region into one of western Odisha's main rice-growing belts. Two hydropower stations, Burla and Chiplima, together generate up to 347.5 MW of electricity. Because so many demands sit on the same water — farmers, industry, and power generation — allocation has occasionally become contentious, including a large protest by farmers over water diverted to industrial users. A renovation programme is now underway to convert ageing earthen canals to concrete, cutting seepage losses and improving water delivery to farms at the tail end of the system."},birdlife:{title:"A Winter Stopover on the Reservoir",subtitle:"Over 130 recorded bird species, with roughly 20 of high conservation significance.",content:"Every winter, migratory waterfowl arrive at Hirakud's open water and shallows, feeding alongside the reservoir's resident bird population. Species commonly recorded include the common pochard, red-crested pochard, and great crested grebe, diving ducks and grebes that favour the reservoir's calmer stretches. The adjoining Debrigarh Wildlife Sanctuary, on the reservoir's northern shore, adds forested habitat that shelters birds and other wildlife moving in and out of the wetland edge.",facts:["Around 20 to 25 waterbird species are regularly seen on the reservoir through the winter months.","Debrigarh Wildlife Sanctuary borders the reservoir and supports species that use both forest and open water habitats.","The reservoir's scale means birdwatching sites can vary considerably by season, as water levels rise and fall."]},fisheries:{title:"A Livelihood for Thousands of Fishing Households",content:"Hirakud supports around 54 recorded species of fish, several of them of high economic value, alongside a smaller number classed as threatened or near-threatened. Fishing on the reservoir yields roughly 480 tonnes of fish annually and forms the economic backbone for close to 7,000 fisher households living around its shores. Balancing that fishery against water releases for irrigation and power is one of the reservoir's ongoing management challenges, since sudden drawdowns can affect both fish habitat and the safety of small fishing boats on open water."},biodiversity:{title:"Beyond Fish and Flocks",content:"Hirakud's edges and islands host more than birds and fisheries. Cattle Island, a submerged hilltop near the reservoir's upper reaches, is home to a herd of feral cattle descended from animals left behind during the original resettlement of the valley in the 1950s — now wild, wary, and rarely caught. The surrounding forest tracts, including Debrigarh, support a wider mix of wildlife typical of dry deciduous Odisha forest, from deer to smaller mammals, drawn to the reservoir's permanent water source in an otherwise seasonally dry landscape."},hotspots:[{id:"gandhi-minar",name:"Gandhi Minar Viewpoint",lat:21.58,lng:83.87,desc:"Observation tower on the dam's left bank offering sweeping views across the reservoir."},{id:"jawahar-minar",name:"Jawahar Minar Viewpoint",lat:21.58,lng:83.86,desc:"Sister observation tower on the right bank, popular for sunset views over the dam."},{id:"debrigarh",name:"Debrigarh Wildlife Sanctuary",lat:21.62,lng:83.8,desc:"Forested sanctuary bordering the reservoir's northern shore, rich in birdlife and deer."},{id:"cattle-island",name:"Cattle Island",lat:21.75,lng:84.1,desc:"Remote hilltop island inhabited only by descendants of cattle left behind during resettlement."},{id:"chiplima",name:"Chiplima Power House",lat:20.47,lng:83.72,desc:"Second hydropower station on the system, built where the Mahanadi drops over a natural fall."}],gallery:[{title:"Hirakud Dam Panorama",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Hirakud_Dam_Panorama.jpg",caption:"Wide view across the main dam section spanning the Mahanadi River."},{title:"Hirakud Reservoir",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Hirakud_Dam_Reservoir.jpg",caption:"Open water of the reservoir stretching toward the horizon."},{title:"Fisherman on the Reservoir",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Hirakud_fisherman2.jpg",caption:"A local fisherman working the reservoir's waters, part of a livelihood shared by thousands."},{title:"View of Hirakud",url:"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Hirakud.jpg",caption:"A broad view of the reservoir and its shoreline near Sambalpur."}],facts:["The Hirakud Dam and its dykes together stretch 25.8 km, making it the longest earthen dam in the world.","More than 200 villages, and the temples within them, were submerged when the reservoir was first filled — some resurface briefly each summer.","Cattle Island is home to a wild herd descended from cattle left behind during the original resettlement of the valley.","Hirakud is an unusual Ramsar site: a working reservoir that still supplies irrigation, flood control, and hydropower to this day."]};